import json, sys
import websocket
import urllib.request

tabs = json.loads(urllib.request.urlopen("http://localhost:1337/json").read())
page = next(t for t in tabs if t.get("type") == "page")
ws_url = page["webSocketDebuggerUrl"]

ws = websocket.create_connection(ws_url)
mid = 0
def send(method, params=None):
    global mid
    mid += 1
    ws.send(json.dumps({"id": mid, "method": method, "params": params or {}}))
    while True:
        msg = json.loads(ws.recv())
        if msg.get("id") == mid:
            return msg

# Navigate to chrome://policy
print(send("Page.enable"))
print(send("Page.navigate", {"url": "chrome://policy/"}))

# Wait briefly for load
import time
time.sleep(1.5)

# Evaluate JS in the page to click the "Reload policies" button
r = send("Runtime.evaluate", {
    "expression": """
    (async () => {
      const btn = document.querySelector('#reload-policies');
      if (btn) { btn.click(); return 'clicked'; }
      // shadow DOM hunt
      function deepFind(root, sel) {
        const found = root.querySelector(sel);
        if (found) return found;
        const all = root.querySelectorAll('*');
        for (const e of all) {
          if (e.shadowRoot) {
            const f = deepFind(e.shadowRoot, sel);
            if (f) return f;
          }
        }
        return null;
      }
      const b = deepFind(document, '#reload-policies') || deepFind(document, 'cr-button');
      if (b) { b.click(); return 'clicked-deep'; }
      return 'not-found';
    })();
    """,
    "awaitPromise": True,
    "returnByValue": True
})
print(json.dumps(r, indent=2)[:2000])

time.sleep(1.5)

# Now scrape policy table to confirm ClearBrowsingDataOnExitList is present
r = send("Runtime.evaluate", {
    "expression": """
    (() => {
      function deepText(root) {
        return root ? (root.innerText || '') : '';
      }
      function deepQueryAll(root, sel, acc=[]) {
        acc.push(...root.querySelectorAll(sel));
        root.querySelectorAll('*').forEach(e => {
          if (e.shadowRoot) deepQueryAll(e.shadowRoot, sel, acc);
        });
        return acc;
      }
      const text = document.body ? document.body.innerText : '';
      const hasName = text.includes('ClearBrowsingDataOnExitList');
      return { hasName, snippet: text.slice(0, 1500) };
    })();
    """,
    "returnByValue": True
})
print(json.dumps(r, indent=2)[:3000])
ws.close()

